assert set(copy) == {c['id'] for c in data['vehicles']}
ledger=[]
for car in data['vehicles']:
    cid=car['id']; name,intro=copy[cid]
    km=f"{car['mile']:,}".replace(',', ' ')
    price=f"R {car['value']:,}".replace(',', ' ')
    details=f"This {car['colour'].lower()} example has a recorded mileage of {km} km and is advertised at {price}. Its stock reference is {car['stock_code']}. Contact Driving Force to confirm availability, discuss the vehicle’s history and fitted equipment, or arrange a viewing at the Montague Gardens showroom."
    car.update(displayName=name, description=[intro,details], features=features.get(cid,[]), descriptionSource='original-listing' if cid in archives else 'inventory-facts')
    ledger.append({'id':cid,'stockCode':car['stock_code'],'vehicle':f"{car['year']} {name}",'sourceType':car['descriptionSource'],'inventoryDate':data['retrieved'],'originalUrl':car['permaLink'],'archiveUrl':archives[cid]['url'] if cid in archives else None,'archiveSha256':extracted[cid]['sha256'] if cid in archives else None,'matchedOn':['stock reference','year','variant','primary image asset'] if cid in archives else ['exact inventory record'],'equipmentDataAvailable':cid in features,'notes': 'Original text paraphrased; dated prices, mileage, condition, service history, warranties and unsupported comparisons excluded. Current inventory facts retained.' if cid in archives else 'Original copy limited to recorded year, make, variant, body type, fuel, transmission, colour, mileage, price and stock reference. No equipment or history claims added.'})
